UndertowAudioProcessorEditor::UndertowAudioProcessorEditor(UndertowAudioProcessor& p)
    : AudioProcessorEditor(&p), processor(p)
{
    setLookAndFeel(&lnf);

    // ── SOUND SOURCE ────────────────────────────────────────────────────────
    auto& voicing = addSection("VOICING");
    addCombo(voicing, Params::polyphonyMode, "Mode",
             "Poly: multiple simultaneous voices. Mono: single voice with glide.");
    addKnob(voicing, Params::glideTimeMs, "Glide",
            "Portamento time — how long to slide between notes in mono mode.");
    addToggle(voicing, Params::legato, "Legato",
              "In legato mode the amplitude envelope does not retrigger on overlapping notes.");

    auto& osc = addSection("OSCILLATOR");
    addCombo(osc, Params::oscModel, "Model",
             "Oscillator engine: Analog (dual-osc), Wavetable (morphable tables), or FM (frequency modulation).");
    addCombo(osc, Params::oscWaveA, "Wave A",   "Primary oscillator waveform.");
    addCombo(osc, Params::oscWaveB, "Wave B",   "Secondary oscillator waveform mixed with Wave A.");
    addKnob(osc,  Params::oscBGain, "B Gain",   "Level of the secondary oscillator (Wave B).");
    addKnob(osc,  Params::oscBPitch, "B Pitch", "Pitch offset of Wave B in semitones. -12 = sub-octave.");
    addToggle(osc, Params::hardSync, "Hard Sync",
              "Resets oscillator B's phase to A's — creates rich harmonic sweeps when pitch changes.");
    addKnob(osc, Params::pulseWidth, "PW",       "Pulse width. 0.5 = square; lower/higher = thinner pulse.");
    addKnob(osc, Params::wtPosition, "WT Pos",   "Position through the wavetable — morphs between waveforms.");
    addKnob(osc, Params::wtWarp,     "WT Warp",  "Warps the wavetable lookup for additional harmonic content.");
    addKnob(osc, Params::fmRatio,    "FM Ratio", "FM modulator-to-carrier frequency ratio.");
    addKnob(osc, Params::fmIndex,    "FM Idx",   "FM modulation depth — higher = more sidebands and brightness.");
    addKnob(osc, Params::fmFeedback, "FM Fdbk",  "FM self-feedback — adds chaos and distortion.");
    addKnob(osc, Params::oscOctave,   "Octave",  "Transpose oscillator by whole octaves.");
    addKnob(osc, Params::oscSemitone, "Semi",    "Transpose oscillator by semitones.");
    addKnob(osc, Params::oscFineCents,"Fine",     "Fine-tune in cents (1/100th semitone).");
    addKnob(osc, Params::unisonVoices,"Unison",  "Number of detuned oscillator copies layered together.");
    addKnob(osc, Params::unisonDetune,"Detune",  "Detune spread between unison voices in cents.");
    addKnob(osc, Params::unisonSpread,"Spread",  "Stereo spread of unison voices.");

    auto& bands = addSection("3-BAND");
    addToggle(bands, Params::bandsEnable,   "3-Band",
              "Enable 3-band mode — each spectral region (Body/Character/Air) runs its own oscillator.");
    addKnob(bands, Params::crossoverLow,  "X-Low",
            "Crossover frequency between Body (sub/low) and Character (mid) bands.");
    addKnob(bands, Params::crossoverHigh, "X-High",
            "Crossover frequency between Character (mid) and Air (high) bands.");

    auto& am = addSection("AM INJECT");
    addKnob(am,  Params::amAmount, "Amount",
            "Depth of amplitude modulation — Body band modulates the level of upper bands.");
    addCombo(am, Params::amTarget, "Target",
             "Which upper bands are AM-modulated by the Body band.");

    // ── 3-BAND SECTIONS ─────────────────────────────────────────────────────
    auto makeBand = [&](const juce::String& name,
                        const char* model, const char* gain, const char* pan,
                        const char* pitch, const char* active, const char* drive,
                        const char* fon, const char* ftype, const char* fcut, const char* fres)
    {
        auto& s = addSection(name);
        addCombo(s,  model,  "Model",    "Oscillator type for this band.");
        addKnob(s,   gain,   "Gain",     "Output level for this band.");
        addKnob(s,   pan,    "Pan",      "Stereo pan position for this band.");
        addKnob(s,   pitch,  "Pitch",    "Pitch offset for this band in semitones.");
        addToggle(s, active, "On",       "Enable or disable this band.");
        addKnob(s,   drive,  "Drive",    "Per-band saturation/overdrive.");
        addToggle(s, fon,    "Filter",   "Enable the per-band filter.");
        addCombo(s,  ftype,  "Flt Type", "Filter type for this band.");
        addKnob(s,   fcut,   "Flt Cut",  "Per-band filter cutoff frequency.");
        addKnob(s,   fres,   "Flt Res",  "Per-band filter resonance.");
    };
    makeBand("BODY",      Params::bodyModel, Params::bodyGain, Params::bodyPan, Params::bodyPitch,
             Params::bodyActive, Params::bodyDrive, Params::bodyFilterOn, Params::bodyFilterType,
             Params::bodyFilterCut, Params::bodyFilterRes);
    makeBand("CHARACTER", Params::charModel, Params::charGain, Params::charPan, Params::charPitch,
             Params::charActive, Params::charDrive, Params::charFilterOn, Params::charFilterType,
             Params::charFilterCut, Params::charFilterRes);
    makeBand("AIR",       Params::airModel,  Params::airGain,  Params::airPan,  Params::airPitch,
             Params::airActive,  Params::airDrive,  Params::airFilterOn,  Params::airFilterType,
             Params::airFilterCut,  Params::airFilterRes);

    // ── DYNAMICS ─────────────────────────────────────────────────────────────
    auto& filt = addSection("FILTER");
    addCombo(filt, Params::filterType,      "Type",     "Filter topology: Low Pass, High Pass, Band Pass, or Notch.");
    addKnob(filt,  Params::filterCutoff,    "Cutoff",   "Filter cutoff frequency — primary tonal shaping control.");
    addKnob(filt,  Params::filterResonance, "Resonance","Resonance adds emphasis at cutoff. High values self-oscillate.");
    addKnob(filt,  Params::filterDrive,     "Drive",    "Pre-filter saturation — warms the sound.");
    addKnob(filt,  Params::filterEnvAmount, "Env Amt",  "How much the Mod Envelope sweeps the filter cutoff.");
    addKnob(filt,  Params::filterKeyTrack,  "Key Track","Filter cutoff tracks MIDI pitch proportionally.");

    auto& ampEnv = addSection("AMP ENV");
    addKnob(ampEnv, Params::ampAttack,  "Attack",  "Time to rise from 0 to peak after note-on.");
    addKnob(ampEnv, Params::ampDecay,   "Decay",   "Time to fall from peak to the sustain level.");
    addKnob(ampEnv, Params::ampSustain, "Sustain", "Level held while note is pressed. 0 = pluck style.");
    addKnob(ampEnv, Params::ampRelease, "Release", "Time to fade to silence after note is released.");

    auto& modEnv = addSection("MOD ENV");
    addKnob(modEnv, Params::modAttack,  "Attack",  "Mod envelope attack — controls filter sweep opening speed.");
    addKnob(modEnv, Params::modDecay,   "Decay",   "Mod envelope decay — how fast the filter sweep closes.");
    addKnob(modEnv, Params::modSustain, "Sustain", "Mod envelope sustain level for the filter sweep.");
    addKnob(modEnv, Params::modRelease, "Release", "Filter sweep tail length after note release.");

    auto& lfoSection = addSection("LFO");
    addCombo(lfoSection, Params::lfoShape,       "Shape",  "LFO waveform: Sine (smooth), Square (choppy), S&H (random step).");
    addKnob(lfoSection,  Params::lfoRate,        "Rate",   "LFO speed in Hz.");
    addKnob(lfoSection,  Params::lfoDepth,       "Depth",  "LFO modulation amount.");
    addCombo(lfoSection, Params::lfoDestination, "Target", "What the LFO modulates: Pitch (vibrato), Filter (wah), or PW.");

    // ── FX & OUTPUT ──────────────────────────────────────────────────────────
    auto& output = addSection("OUTPUT");
    addKnob(output, Params::masterDrive, "Drive", "Master soft-clip saturation on the final output.");
    addKnob(output, Params::masterGain,  "Gain",  "Master output level in dB.");

    auto& fx = addSection("CHORUS + DELAY");
    addToggle(fx, Params::chorusEnable,   "Chorus",   "Enable chorus — thickens the sound with modulated short delays.");
    addKnob(fx,   Params::chorusRate,     "Rate",     "Chorus LFO speed.");
    addKnob(fx,   Params::chorusDepth,    "Depth",    "Chorus modulation depth — more = thicker, more detuned.");
    addKnob(fx,   Params::chorusFeedback, "Feedback", "Chorus feedback — adds resonance to the chorus.");
    addKnob(fx,   Params::chorusMix,      "Mix",      "Chorus wet/dry mix.");
    addToggle(fx, Params::delayEnable,    "Delay",    "Enable stereo ping-pong delay.");
    addKnob(fx,   Params::delayTimeMs,    "Time",     "Delay time in milliseconds.");
    addKnob(fx,   Params::delayFeedback,  "Feedback", "Delay feedback — higher = more repeats.");
    addKnob(fx,   Params::delayMix,       "Mix",      "Delay wet/dry mix.");

    auto& rev = addSection("REVERB");
    addToggle(rev, Params::reverbEnable, "Reverb", "Enable room reverb — adds space and dimension.");
    addKnob(rev,   Params::reverbRoom,   "Room",   "Room size — larger = longer, more diffuse tail.");
    addKnob(rev,   Params::reverbDamp,   "Damp",   "High-frequency damping — higher = darker, warmer reverb.");
    addKnob(rev,   Params::reverbWet,    "Wet",    "Reverb wet level — how much reverb is blended in.");
    addKnob(rev,   Params::reverbWidth,  "Width",  "Stereo width of the reverb field.");

    // Tab buttons — one per section row.
    const char* tabNames[numTabs] = { "SOURCE", "3-BAND", "DYNAMICS", "FX" };
    for (int i = 0; i < numTabs; ++i)
    {
        tabButtons[i].setButtonText(tabNames[i]);
        tabButtons[i].setClickingTogglesState(false);
        tabButtons[i].onClick = [this, i]() { setActiveTab(i); };
        tabButtons[i].setTooltip("Show the " + juce::String(tabNames[i]) + " controls");
        addAndMakeVisible(tabButtons[i]);
    }

    // Show only the active tab's controls from the start.
    updateControlVisibility();

    setResizable(true, true);
    setResizeLimits(800, 300, 1800, 900);
    setSize(960, 480);
    resized();

    // Load logo image from embedded binary data if available.
#if BP_HAS_LOGO_BINARY
    logoImage = juce::ImageCache::getFromMemory(LogoBinaryData::logo_png,
                                                LogoBinaryData::logo_png_size);
#endif

    // Email link in the header — matches the dim text colour used for branding.
    emailLink.setFont(juce::Font(11.0f), false, juce::Justification::topRight);
    emailLink.setColour(juce::HyperlinkButton::textColourId, BPColours::textDim);
    addAndMakeVisible(emailLink);

    // Preset selector in the header.
    addAndMakeVisible(presetBox);
    addAndMakeVisible(prevButton);
    addAndMakeVisible(nextButton);
    presetBox.setTextWhenNothingSelected("Presets");
    populatePresetBox();
    syncPresetBox();
    presetBox.onChange = [this]() { applyPresetByBoxId(presetBox.getSelectedId()); };
    prevButton.onClick = [this]() { stepPreset(-1); };
    presetBox.setTooltip("300 presets by genre. Use < > to step through them.");
    prevButton.setTooltip("Previous preset");
    nextButton.setTooltip("Next preset");
    nextButton.onClick = [this]() { stepPreset(1); };

    // Preset selector colours — neon green text so name and description pop.
    presetBox.setColour(juce::ComboBox::textColourId, BPColours::neonGreen);

    // Preset description label.
    presetDescription.setFont(juce::Font(11.5f, juce::Font::italic));
    presetDescription.setColour(juce::Label::textColourId, BPColours::neonGreen);
    presetDescription.setJustificationType(juce::Justification::centredLeft);
    addAndMakeVisible(presetDescription);
    updatePresetDescription();
}

UndertowAudioProcessorEditor::Section& UndertowAudioProcessorEditor::addSection(const juce::String& title)
{
    sections.push_back(std::make_unique<Section>());
    auto& section = *sections.back();
    section.title = title;
    return section;
}


