UndertowAudioProcessorEditor::Knob& UndertowAudioProcessorEditor::addKnob(
    Section& section, const juce::String& paramID, const juce::String& labelText,
    const juce::String& tip)
{
    allKnobs.push_back(std::make_unique<Knob>());
    auto& knob = *allKnobs.back();

    knob.slider.setTextBoxStyle(juce::Slider::TextBoxBelow, false, 60, 16);
    knob.slider.setMouseDragSensitivity(180);   // snappier: less travel per turn
    const juce::String tipText = tip.isNotEmpty() ? tip : bpTooltip(paramID);
    knob.slider.setTooltip(tipText);
    addAndMakeVisible(knob.slider);

    knob.label.setText(labelText, juce::dontSendNotification);
    knob.label.setJustificationType(juce::Justification::centred);
    knob.label.setFont(juce::Font(11.5f));
    knob.label.setTooltip(tipText);
    addAndMakeVisible(knob.label);

    knob.attachment = std::make_unique<APVTS::SliderAttachment>(processor.apvts, paramID, knob.slider);
    if (auto* prm = processor.apvts.getParameter(paramID))
        knob.slider.setDoubleClickReturnValue(true, (double) processor.apvts.getParameterRange(paramID).convertFrom0to1(prm->getDefaultValue()));

    section.knobs.push_back(&knob);
    return knob;
}

UndertowAudioProcessorEditor::Combo& UndertowAudioProcessorEditor::addCombo(
    Section& section, const juce::String& paramID, const juce::String& labelText,
    const juce::String& tip)
{
    allCombos.push_back(std::make_unique<Combo>());
    auto& combo = *allCombos.back();

    if (auto* param = dynamic_cast<juce::AudioParameterChoice*>(processor.apvts.getParameter(paramID)))
        combo.box.addItemList(param->choices, 1);

    const juce::String comboTip = tip.isNotEmpty() ? tip : bpTooltip(paramID).upToFirstOccurrenceOf("  (", false, false);
    combo.box.setTooltip(comboTip);
    addAndMakeVisible(combo.box);

    combo.label.setText(labelText, juce::dontSendNotification);
    combo.label.setJustificationType(juce::Justification::centred);
    combo.label.setFont(juce::Font(11.5f));
    combo.label.setTooltip(comboTip);
    addAndMakeVisible(combo.label);

    combo.attachment = std::make_unique<APVTS::ComboBoxAttachment>(processor.apvts, paramID, combo.box);

    section.combos.push_back(&combo);
    return combo;
}

UndertowAudioProcessorEditor::Toggle& UndertowAudioProcessorEditor::addToggle(
    Section& section, const juce::String& paramID, const juce::String& labelText,
    const juce::String& tip)
{
    allToggles.push_back(std::make_unique<Toggle>());
    auto& toggle = *allToggles.back();

    toggle.button.setButtonText(labelText);
    toggle.button.setTooltip(tip.isNotEmpty() ? tip : bpTooltip(paramID).upToFirstOccurrenceOf("  (", false, false));
    addAndMakeVisible(toggle.button);

    toggle.attachment = std::make_unique<APVTS::ButtonAttachment>(processor.apvts, paramID, toggle.button);

    section.toggles.push_back(&toggle);
    return toggle;
}

UndertowAudioProcessorEditor::~UndertowAudioProcessorEditor()
{
    setLookAndFeel(nullptr);
}

void UndertowAudioProcessorEditor::populatePresetBox()
{
    presetBox.clear(juce::dontSendNotification);
    auto* menu = presetBox.getRootMenu();

    const int n = processor.getNumBassPresets();
    const auto names = processor.getBassPresetNames();

    juce::String lastCategory;
    for (int i = 0; i < n; ++i)
    {
        const auto cat = processor.getBassPresetCategory(i);
        if (cat != lastCategory)
        {
            menu->addSectionHeader(cat);
            lastCategory = cat;
        }
        // Item ID = index + 1 (0 is reserved for "nothing selected").
        presetBox.addItem(names[i], i + 1);
    }
}

void UndertowAudioProcessorEditor::syncPresetBox()
{
    const int cur = processor.getCurrentBassPreset();
    if (cur >= 0)
        presetBox.setSelectedId(cur + 1, juce::dontSendNotification);
}

void UndertowAudioProcessorEditor::applyPresetByBoxId(int comboId)
{
    if (comboId <= 0)
        return;
    processor.applyBassPreset(comboId - 1);
    updatePresetDescription();
    // APVTS attachments update every control automatically when params change.
}

void UndertowAudioProcessorEditor::stepPreset(int delta)
{
    const int n = processor.getNumBassPresets();
    if (n == 0)
        return;
    int next = processor.getCurrentBassPreset() + delta;
    next = (next % n + n) % n; // wrap
    presetBox.setSelectedId(next + 1, juce::sendNotificationSync);
    updatePresetDescription();
}

void UndertowAudioProcessorEditor::updatePresetDescription()
{
    const int cur = processor.getCurrentBassPreset();
    if (cur >= 0)
        presetDescription.setText(processor.getBassPresetDescription(cur),
                                   juce::dontSendNotification);
    else
        presetDescription.setText({}, juce::dontSendNotification);
}

void UndertowAudioProcessorEditor::setActiveTab(int index)
{
    activeTab = juce::jlimit(0, numTabs - 1, index);
    updateControlVisibility();
    resized();
    repaint();
}

void UndertowAudioProcessorEditor::updateControlVisibility()
{
    // Row→section index mapping (mirrors rowDefs in resized()).
    const std::vector<std::vector<size_t>> rowDefs = {
        { 0, 1, 2, 3 },   // SOURCE
        { 4, 5, 6 },       // 3-BAND
        { 7, 8, 9, 10 },   // DYNAMICS
        { 11, 12, 13 },    // FX
    };

    for (int row = 0; row < numTabs; ++row)
    {
        const bool vis = (row == activeTab);
        for (size_t idx : rowDefs[row])
        {
            if (idx >= sections.size()) continue;
            auto& s = *sections[idx];
            for (auto* k : s.knobs)   { k->slider.setVisible(vis); k->label.setVisible(vis); }
            for (auto* c : s.combos)  { c->box.setVisible(vis); c->label.setVisible(vis); }
            for (auto* t : s.toggles) { t->button.setVisible(vis); }
        }
    }

    // Highlight the active tab button.
    for (int i = 0; i < numTabs; ++i)
    {
        tabButtons[i].setColour(juce::TextButton::buttonColourId,
            i == activeTab ? BPColours::accent.withAlpha(0.8f)
                           : BPColours::panel.withMultipliedBrightness(0.6f));
        tabButtons[i].setColour(juce::TextButton::textColourOnId,
            i == activeTab ? juce::Colours::black : BPColours::textBright);
        tabButtons[i].setColour(juce::TextButton::textColourOffId,
            i == activeTab ? juce::Colours::black : BPColours::textBright);
    }
}

void UndertowAudioProcessorEditor::paint(juce::Graphics& g)
{
    auto bounds = getLocalBounds();

    // Background gradient
    juce::ColourGradient bg(BPColours::bgTop, 0.0f, 0.0f,
                             BPColours::bgBottom, 0.0f, (float) getHeight(), false);
    g.setGradientFill(bg);
    g.fillRect(bounds);

    // Logo as full-bleed watermark at the bottom of the layer stack.
    // MUST be drawn before any fills — panels use borders only (no fill)
    // so the logo shows through at full opacity.
    if (logoImage.isValid())
    {
        g.setOpacity(0.30f);
        g.drawImage(logoImage, getLocalBounds().toFloat(),
                    juce::RectanglePlacement::centred | juce::RectanglePlacement::fillDestination);
        g.setOpacity(1.0f);
    }

    // Header bar
    auto header = bounds.removeFromTop(headerHeight);
    g.setColour(BPColours::panel);
    g.fillRect(header);
    g.setColour(BPColours::accent);
    g.fillRect(header.removeFromBottom(2)); // accent underline

    // Title block \u2014 logo thumbnail on the left, wordmark text always shown.
    static constexpr int titleBlockW = 260;
    const int logoSize = headerHeight - 8;
    if (logoImage.isValid())
    {
        g.drawImageWithin(logoImage, 4, 4, logoSize, logoSize,
                          juce::RectanglePlacement::centred | juce::RectanglePlacement::onlyReduceInSize,
                          false);
    }
    const int textX = logoImage.isValid() ? logoSize + 8 : 10;
    // "BASS PROFESSOR" wordmark
    g.setColour(BPColours::accent);
    g.setFont(juce::Font(20.0f, juce::Font::bold));
    g.drawText("BASS PROFESSOR",
                juce::Rectangle<int>(textX, 6, titleBlockW - textX - 4, headerHeight - 24),
                juce::Justification::bottomLeft, false);
    g.setColour(BPColours::textDim);
    g.setFont(juce::Font(10.0f));
    g.drawText("3-BAND BASS SYNTHESIZER",
                juce::Rectangle<int>(textX, headerHeight - 20, titleBlockW - textX - 4, 16),
                juce::Justification::centredLeft, false);

    // Tully EDM Vibe logo, left of the copyright / email block
    {
        static const juce::Image tully = juce::ImageCache::getFromMemory (TullyLogoData::png, (int) TullyLogoData::pngSize);
        if (tully.isValid())
        {
            const int lh = headerHeight - 10;
            g.drawImageWithin (tully, getWidth() - 8 - 180 - 6 - lh, 5, lh, lh, juce::RectanglePlacement::centred, false);
        }
    }
    // Branding (right side of header)
    g.setColour(BPColours::textDim);
    g.setFont(juce::Font(11.0f));
    auto brand = juce::Rectangle<int>(getWidth() - 360, 8, 344, headerHeight - 12);
    g.drawText(juce::String::fromUTF8("\u00A9\u2117 2026 Tully EDM Vibe"),
                brand.removeFromTop(18), juce::Justification::topRight, false);
    // email drawn by emailLink HyperlinkButton \u2014 no static text here

    // Tab strip underline.
    g.setColour(BPColours::accent.withAlpha(0.5f));
    g.fillRect(0, headerHeight + tabStripH - 2, getWidth(), 2);

    // Active row zone only.
    const juce::Colour rowStripe[4] = {
        BPColours::accent,
        BPColours::neonGreen.withAlpha(0.7f),
        juce::Colour(0xff5080ff),
        juce::Colour(0xffaa44dd),
    };
    if (activeTab < (int) rowZones.size())
    {
        auto zone = rowZones[activeTab].toFloat().expanded(2.0f);
        g.setColour(rowStripe[activeTab].withAlpha(0.15f));
        g.drawRoundedRectangle(zone, 8.0f, 1.0f);
        auto stripe = zone.withWidth(4.0f).reduced(0, 4.0f);
        g.setColour(rowStripe[activeTab].withAlpha(0.85f));
        g.fillRoundedRectangle(stripe, 2.0f);
    }

    // Section panels — only draw sections that belong to the active tab.
    for (auto& sectionPtr : sections)
    {
        auto& section = *sectionPtr;
        if (section.bounds.isEmpty())
            continue;
        auto r = section.bounds.toFloat();

        // No fill — logo shows through. Just a subtle border so the panel
        // boundary is visible. A very faint dark tint helps text readability.
        g.setColour(juce::Colours::black.withAlpha(0.35f));
        g.fillRoundedRectangle(r, 7.0f);
        g.setColour(BPColours::panelEdge.withAlpha(0.6f));
        g.drawRoundedRectangle(r, 7.0f, 1.0f);

        // Section title bar — amber gradient strip across the top
        auto titleR = r.removeFromTop(24.0f);
        juce::ColourGradient titleGrad(BPColours::accent.withAlpha(0.18f), titleR.getX(), titleR.getY(),
                                        juce::Colours::transparentBlack, titleR.getX(), titleR.getBottom(), false);
        g.setGradientFill(titleGrad);
        g.fillRoundedRectangle(titleR, 7.0f);

        // Amber pip on left, title text
        g.setColour(BPColours::accent);
        g.fillRect(titleR.withWidth(3.0f).reduced(0.0f, 4.0f));
        g.setColour(BPColours::textBright);
        g.setFont(juce::Font(11.5f, juce::Font::bold));
        g.drawText(section.title, titleR.withTrimmedLeft(9.0f).toNearestInt(),
                    juce::Justification::centredLeft, false);
    }
}

void UndertowAudioProcessorEditor::resized()
{
    // ── Email hyperlink (right side of header, below copyright line) ─────────
    {
        // Matches the brand rect in paint(): right-aligned, 160px wide, at y=26 (8+18)
        const int linkW = 180;
        emailLink.setBounds(getWidth() - 8 - linkW, 26, linkW, 16);
    }

    // ── Header preset block ──────────────────────────────────────────────────
    {
        static constexpr int presetLeft = 270;
        static constexpr int boxW       = 320;
        static constexpr int btnW       = 28;
        static constexpr int btnH       = 26;
        const int by   = (headerHeight / 2 - btnH) / 2 + 2;
        const int descY = by + btnH + 3;
        prevButton.setBounds(presetLeft, by, btnW, btnH);
        presetBox.setBounds(presetLeft + btnW + 4, by, boxW, btnH);
        nextButton.setBounds(presetLeft + btnW + 4 + boxW + 4, by, btnW, btnH);
        presetDescription.setBounds(presetLeft + btnW + 4, descY, boxW + btnW + 4, 15);
    }

    // ── Tab buttons (strip just below the header) ────────────────────────────
    {
        const int tabY  = headerHeight + 4;
        const int tabH  = tabStripH - 8;
        const int tabW  = 110;
        const int tabGp = 4;
        for (int i = 0; i < numTabs; ++i)
            tabButtons[i].setBounds(10 + i * (tabW + tabGp), tabY, tabW, tabH);
    }

    // ── Content area (below header + tab strip) ───────────────────────────────
    auto full = getLocalBounds();
    full.removeFromTop(headerHeight + tabStripH);
    auto bounds = full.reduced(10);
    bounds.removeFromTop(10); // small top margin

    // Control cell dimensions.
    static constexpr int cw = 70;
    static constexpr int ch = 76;
    static constexpr int titleH = 22;
    static constexpr int secPad = 10;
    static constexpr int secGap = 6;

    auto natW = [&](int count, int forceCols = 0) -> int {
        const int cols = forceCols > 0 ? forceCols
                         : juce::jmax(2, (int) std::ceil(std::sqrt((double) count)));
        return cols * cw + secPad;
    };
    auto natH = [&](int count, int forceCols = 0) -> int {
        const int cols = forceCols > 0 ? forceCols
                         : juce::jmax(2, (int) std::ceil(std::sqrt((double) count)));
        const int rows = (count + cols - 1) / cols;
        return rows * ch + titleH + 8;
    };
    auto ctrlCount = [&](size_t idx) -> int {
        if (idx >= sections.size()) return 0;
        auto& s = *sections[idx];
        return (int) (s.knobs.size() + s.combos.size() + s.toggles.size());
    };

    // Section row definitions (same as before).
    const std::vector<std::vector<size_t>> rowDefs = {
        { 0, 1, 2, 3 },   // SOURCE
        { 4, 5, 6 },       // 3-BAND
        { 7, 8, 9, 10 },   // DYNAMICS
        { 11, 12, 13 },    // FX
    };

    // Zero all section bounds; only the active tab's sections will be set.
    for (auto& s : sections)
        s->bounds = {};

    rowZones.clear();
    rowZones.resize(numTabs); // keep indexed by tab number

    const auto& activeRow = rowDefs[activeTab];

    // Compute row height.
    int rowH = 0;
    int totalNatW = 0;
    for (size_t idx : activeRow)
    {
        rowH = juce::jmax(rowH, natH(ctrlCount(idx)));
        totalNatW += natW(ctrlCount(idx));
    }
    totalNatW += (int) (activeRow.size() - 1) * secGap;

    const int extra    = juce::jmax(0, bounds.getWidth() - totalNatW);
    const int extraPer = extra / juce::jmax(1, (int) activeRow.size());

    int x = bounds.getX();
    int y = bounds.getY();
    for (size_t idx : activeRow)
    {
        if (idx >= sections.size()) continue;
        auto& section = *sections[idx];
        const int secW = natW(ctrlCount(idx)) + extraPer;
        section.bounds = { x, y, secW, rowH };
        x += secW + secGap;
    }

    rowZones[activeTab] = { bounds.getX(), y, bounds.getWidth(), rowH };

    requiredHeight = y + rowH + 20 + headerHeight + tabStripH;

    // ── Place controls within each section (active tab only) ─────────────────
    for (auto& sectionPtr : sections)
    {
        auto& section = *sectionPtr;
        if (section.bounds.isEmpty())
            continue;
        const int count = (int) (section.knobs.size() + section.combos.size() + section.toggles.size());
        const int cols  = juce::jmax(2, (int) std::ceil(std::sqrt((double) count)));

        // Inner area below the title bar
        auto area = section.bounds.reduced(secPad / 2, 4);
        area.removeFromTop(titleH);
        const int rightEdge = area.getX() + cols * cw;
        int cx = area.getX();
        int cy = area.getY();

        auto advance = [&]()
        {
            cx += cw;
            if (cx + cw > rightEdge + 1)
            {
                cx = area.getX();
                cy += ch;
            }
        };

        for (auto* k : section.knobs)
        {
            k->slider.setBounds(cx + 2, cy + 2, cw - 4, ch - 20);
            k->label.setBounds(cx, cy + ch - 20, cw, 16);
            advance();
        }
        for (auto* c : section.combos)
        {
            c->label.setBounds(cx + 2, cy + 2, cw - 4, 14);
            c->box.setBounds(cx + 2, cy + 18, cw - 4, 24);
            advance();
        }
        for (auto* t : section.toggles)
        {
            t->button.setBounds(cx + 4, cy + (ch / 2 - 11), cw - 8, 22);
            advance();
        }
    }
}
